import{_ as l,o as i,c as e,a2 as r}from"./chunks/framework.CdvW4CUT.js";const q=JSON.parse('{"title":"活動協助申請","description":"玩家自辦企劃活動的協助申請及說明。","frontmatter":{"title":"活動協助申請","description":"玩家自辦企劃活動的協助申請及說明。"},"headers":[],"relativePath":"apply/plan/index.md","filePath":"apply/plan.md"}'),t={name:"apply/plan/index.md"};function o(h,a,n,u,d,s){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="活動協助申請" tabindex="-1">活動協助申請 <a class="header-anchor" href="#活動協助申請" aria-label="Permalink to &quot;活動協助申請&quot;">​</a></h1><h2 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to &quot;介紹&quot;">​</a></h2><p>我們鼓勵玩家們舉辦任何公開或私人的活動，促進玩家間的交流與互動，這些都能對本伺服帶來良好的效益。<br> 若玩家有想法或行動，想要舉辦這種類型的活動，認為<strong>需要由伺服方出面協助時</strong>，可以與我們聯繫取得相關協助，本篇文將會說明你該如何進行。</p><p>若有任何第三方社群或商業合作，建議可直接聯繫本<a href="/discord/">伺服Discord</a> Discord ID：<code>miunapa</code></p><h2 id="有什麼是我們可以幫上忙的" tabindex="-1">有什麼是我們可以幫上忙的 <a class="header-anchor" href="#有什麼是我們可以幫上忙的" aria-label="Permalink to &quot;有什麼是我們可以幫上忙的&quot;">​</a></h2><ul><li>活動宣傳 <ul><li>不限定於本伺服或本遊戲，若想協助宣傳第三方遊戲也可協助，我們非常歡迎玩家舉辦各式不同種類的活動</li></ul></li><li>伺服人員的現場協助、監督、主持、參與等人工作業</li><li>物品獎勵的美化 : 更改物品名字(彩色字)/增加物品敘述 <code>500元一件</code></li><li>臨時的領地劃設，避免場地遭受惡意破壞</li><li>臨時傳送點設置，供玩家可以直接性的傳送</li><li>協助提供專用場地或伺服</li><li>功能或系統的協助開發與設定使用</li><li>任何討論中可能需要，且我們有辦法完成之協助</li></ul><h2 id="申請方式" tabindex="-1">申請方式 <a class="header-anchor" href="#申請方式" aria-label="Permalink to &quot;申請方式&quot;">​</a></h2><ol><li>請加入<a href="/discord/">伺服Discord</a></li><li>進入『#提問與開發』頻道，接著使用討論串功能建立&quot;公開&quot;討論串</li><li>討論串標題請打上你的活動名稱，建立完成後，請在討論串內提出你的活動，若為外部網站連結，請確保該網站的資料是可以另存下載的。</li><li>最後，在該討論串內直接tag服主MiunaPA，並等待回應。</li></ol><h2 id="申請建議提供的相關資料" tabindex="-1">申請建議提供的相關資料 <a class="header-anchor" href="#申請建議提供的相關資料" aria-label="Permalink to &quot;申請建議提供的相關資料&quot;">​</a></h2><p>伺服方是協助玩家籌備活動或提供資源的角色，實際您需要什麼具體的需求，請務必在活動資料中詳細說明你的內容，越詳細越好，以方便本伺服可以快速理解，並從中協助您的活動籌備。<br> 下方的項目僅為舉例內容，實際還是要依照你的想法去撰寫與說明</p><h3 id="活動名稱與主旨-必需" tabindex="-1">活動名稱與主旨(必需) <a class="header-anchor" href="#活動名稱與主旨-必需" aria-label="Permalink to &quot;活動名稱與主旨(必需)&quot;">​</a></h3><ul><li>請&quot;簡短&quot;說明本活動企劃的<strong>名稱與主要內容</strong></li></ul><h3 id="活動執行時間與地點-必需" tabindex="-1">活動執行時間與地點(必需) <a class="header-anchor" href="#活動執行時間與地點-必需" aria-label="Permalink to &quot;活動執行時間與地點(必需)&quot;">​</a></h3><ul><li><strong>請提供本活動預計會於何時執行與地點</strong></li><li>時間 <ul><li>一個指定時間或一段期間、特殊節慶日子等</li></ul></li><li>地點 <ul><li>若為遊戲內，請附上分流、世界、座標、該地點的名稱(方便後續稱呼) <ul><li>若該地點為多人居住的社區或他人的建築，請務必事先取得場地所有權人同意</li></ul></li><li>若並非本伺服或本遊戲，請敘述為何種遊戲，並詳細說明該如何前往或參加 <ul><li>也請詳細敘述該遊戲的主要內容</li></ul></li></ul></li></ul><h3 id="報名或參加條件" tabindex="-1">報名或參加條件 <a class="header-anchor" href="#報名或參加條件" aria-label="Permalink to &quot;報名或參加條件&quot;">​</a></h3><p>說明一下此活動的主要面向為何</p><ul><li>公開活動 : 任何玩家都可以參加</li><li>私人活動 : 指定玩家、須滿足某種條件或報名才可參加(例如社區活動)...</li></ul><h3 id="任何你需要的幫助及詳細規劃" tabindex="-1">任何你需要的幫助及詳細規劃 <a class="header-anchor" href="#任何你需要的幫助及詳細規劃" aria-label="Permalink to &quot;任何你需要的幫助及詳細規劃&quot;">​</a></h3><ul><li>多多益善，你需要什麼幫助，就詳細說出來，我們才知道該怎麼協助你</li></ul><h3 id="物品獎勵的美化" tabindex="-1">物品獎勵的美化 <a class="header-anchor" href="#物品獎勵的美化" aria-label="Permalink to &quot;物品獎勵的美化&quot;">​</a></h3><p>更改物品名字(彩色字)/增加物品敘述，請提供相關文本及格式化代碼顏色。 考量到特殊物品在玩家間具有其獨特的價值，因此這部分會有一些條件。</p><ul><li>公開與私人活動皆可申請特殊物品</li><li>一件物品的價格為<strong>500元</strong>，且物品需自備，伺服方僅提供刻字與美化服務</li><li>物品會強制寫上活動名稱與活動日期</li><li>物品附魔外觀功能已開放給所有玩家使用，若您有需要此服務，請依照目前的規定價格支付費用</li></ul><h2 id="申請注意事項" tabindex="-1">申請注意事項 <a class="header-anchor" href="#申請注意事項" aria-label="Permalink to &quot;申請注意事項&quot;">​</a></h2><h3 id="請在企劃執行時間『至少』前14日繳交活動" tabindex="-1">請在企劃執行時間『至少』前14日繳交活動 <a class="header-anchor" href="#請在企劃執行時間『至少』前14日繳交活動" aria-label="Permalink to &quot;請在企劃執行時間『至少』前14日繳交活動&quot;">​</a></h3><ul><li>請考量到企劃的討論與審核需要時間，若逾期將不受理</li><li>企劃方也需保留一定時間，以配合企劃的討論</li><li>由於伺服方本身也有許多的規劃日程，請盡可能提早或保留更多的備案日期</li></ul><h3 id="我們需要有你提供的活動企劃-才能讓伺服方知道你需要什麼" tabindex="-1">我們需要有你提供的活動企劃，才能讓伺服方知道你需要什麼 <a class="header-anchor" href="#我們需要有你提供的活動企劃-才能讓伺服方知道你需要什麼" aria-label="Permalink to &quot;我們需要有你提供的活動企劃，才能讓伺服方知道你需要什麼&quot;">​</a></h3><ul><li>提出活動企劃讓伺服方知道你想做什麼很重要，沒有企劃的話，縱使你完成了所有準備工作，我們依然沒辦法幫上忙，希望大家能互相配合，依照正規流程申請，我們都會盡力去協助玩家的</li></ul><h3 id="某些情況下-活動企劃可能無法通過" tabindex="-1">某些情況下，活動企劃可能無法通過 <a class="header-anchor" href="#某些情況下-活動企劃可能無法通過" aria-label="Permalink to &quot;某些情況下，活動企劃可能無法通過&quot;">​</a></h3><ul><li>我們很鼓勵玩家提出企劃，也會盡量去幫忙協助企劃通過與執行，但請考量到伺服方也有一些營運上的整體決策，希望大家能互相理解，我們會盡可能讓大家的企劃都能通過，但也不排除有一些情況，是我們沒辦法審核通過的</li><li>伺服方同意企劃後，也代表企劃方對此企劃需負責，而伺服方也需負起同意後的連帶責任</li></ul><h2 id="活動企劃補助" tabindex="-1">活動企劃補助 <a class="header-anchor" href="#活動企劃補助" aria-label="Permalink to &quot;活動企劃補助&quot;">​</a></h2><p>由於籌備活動需要花費大量的精力與遊戲資源，伺服會視活動企劃評估您是否可以獲得補助，如果您<strong>很需要伺服方進行相關補助的話</strong>，請提供以下說明。</p><h4 id="能增進本伺服的效益" tabindex="-1">能增進本伺服的效益 <a class="header-anchor" href="#能增進本伺服的效益" aria-label="Permalink to &quot;能增進本伺服的效益&quot;">​</a></h4><ul><li>請盡可能的敘述說本活動企劃若能成功執行，對本伺服能帶來的效益 <ul><li>不論是私人或公眾效益都可以，總之盡可能說明</li></ul></li><li>同時也請思考或描述，本活動企劃對全伺服的公平性與合理性 <ul><li>我們希望伺服方對大家都是盡可能公平的，這部分也請留意</li></ul></li></ul>',33)])])}const p=l(t,[["render",o]]);export{q as __pageData,p as default};
